// Drive-IDs der zu indexierenden Bibliotheken (Graph: /sites/{site}/drives)
const DRIVES = [
  // { driveId: 'b!....', label: 'HV Freigegebene Dokumente', source: 'SharePoint' },
  // { driveId: 'b!....', label: 'HV Dokumentvorlagen', source: 'SharePoint' },
  // { driveId: 'b!....', label: 'OneDrive Email attachments from Flow', source: 'OneDrive' },
];
const staticData = $getWorkflowStaticData('global');
return DRIVES.map(d => ({ json: { ...d, deltaLink: staticData['delta_' + d.driveId] || null } }));

// Graph-Items → AX-Dokument-Payload; Ordner und Gelöschtes überspringen.
// Neues deltaLink für den nächsten Lauf sichern.
const staticData = $getWorkflowStaticData('global');
const out = [];
for (const item of $input.all()) {
  const body = item.json;
  if (body['@odata.deltaLink']) staticData['delta_' + $('Drives + Delta-Token').item.json.driveId] = body['@odata.deltaLink'];
  for (const f of body.value || []) {
    if (f.folder || f.deleted) continue;
    const path = (f.parentReference?.path || '').replace(/^\/drives\/[^/]+\/root:?/, '');
    const unit = (path + '/' + f.name).match(/\b(\d{3}-\d{3}(-\d{2})?|[A-Z]-\d{3}-\d{3}-\d{2})\b/);
    out.push({ json: {
      drive_id: f.parentReference?.driveId,
      item_id: f.id,
      source: $('Drives + Delta-Token').item.json.source,
      file_name: f.name,
      file_type: (f.name.split('.').pop() || '').toLowerCase(),
      file_size: f.size,
      web_url: f.webUrl,
      folder_path: path,
      modified_on_source: f.lastModifiedDateTime,
      etag: f.eTag,
      unit_code: unit ? unit[1] : undefined,
    }});
  }
}
return out;
